package config

import (
	"testing"
)

func TestLoad(t *testing.T) {
	data := []byte(`{"host":"localhost","port":8080,"debug":true,"timeout_seconds":30}`)
	cfg, err := Load(data)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if cfg.Host != "localhost" {
		t.Fatalf("want host=localhost, got %q", cfg.Host)
	}
	if cfg.Port != 8080 {
		t.Fatalf("want port=8080, got %d", cfg.Port)
	}
	if !cfg.Debug {
		t.Fatal("want debug=true")
	}
}

func TestLoadInvalidJSON(t *testing.T) {
	_, err := Load([]byte(`not json`))
	if err == nil {
		t.Fatal("want error on invalid JSON, got nil")
	}
}

func TestAddr(t *testing.T) {
	cfg := &ServerConfig{Host: "example.com", Port: 9090}
	if got := cfg.Addr(); got != "example.com:9090" {
		t.Fatalf("want example.com:9090, got %q", got)
	}
}
